PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, email TEXT UNIQUE, tipo TEXT NOT NULL DEFAULT 'estudante', criado_em DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categorias (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL UNIQUE, descricao TEXT, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS perguntas (id INTEGER PRIMARY KEY AUTOINCREMENT, categoria_id INTEGER NOT NULL, enunciado TEXT NOT NULL, dificuldade TEXT NOT NULL DEFAULT 'facil', ativa INTEGER NOT NULL DEFAULT 1, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (categoria_id) REFERENCES categorias(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS alternativas (id INTEGER PRIMARY KEY AUTOINCREMENT, pergunta_id INTEGER NOT NULL, texto TEXT NOT NULL, correta INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (pergunta_id) REFERENCES perguntas(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tentativas_quiz (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER, pontuacao INTEGER NOT NULL DEFAULT 0, total_perguntas INTEGER NOT NULL DEFAULT 0, total_acertos INTEGER NOT NULL DEFAULT 0, total_erros INTEGER NOT NULL DEFAULT 0, criado_em DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS respostas_usuario (id INTEGER PRIMARY KEY AUTOINCREMENT, tentativa_id INTEGER NOT NULL, pergunta_id INTEGER NOT NULL, alternativa_id INTEGER NOT NULL, correta INTEGER NOT NULL DEFAULT 0, respondido_em DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (tentativa_id) REFERENCES tentativas_quiz(id) ON DELETE CASCADE, FOREIGN KEY (pergunta_id) REFERENCES perguntas(id) ON DELETE CASCADE, FOREIGN KEY (alternativa_id) REFERENCES alternativas(id) ON DELETE CASCADE);
